    const promptText = parts?.filter((p) => p.type === "text" && p.text).map((p) => p.text).join(`
`).trim() || "";
    if (!promptText.includes("<session-context>") || !promptText.includes(START_WORK_TEMPLATE_MARKER)) {
      return;
    }
