// src/hooks/atlas/boulder-session-lineage.ts
init_logger();
async function isSessionInBoulderLineage(input) {
  const normalizedBoulderSessionIDs = input.boulderSessionIDs.map((sessionID) => normalizeSessionId(sessionID));
  const visitedSessionIDs = new Set;
  let currentSessionID = input.sessionID;
  while (!visitedSessionIDs.has(currentSessionID)) {
    visitedSessionIDs.add(currentSessionID);
    const sessionResult = await input.client.session.get({ path: { id: currentSessionID } }).catch((error) => {
      log(`[${HOOK_NAME7}] Failed to resolve session lineage`, {
        sessionID: input.sessionID,
        currentSessionID,
        error
      });
      return null;
    });
    if (!sessionResult || sessionResult.error) {
      return false;
    }
    const parentSessionID = sessionResult.data?.parentID;
    if (!parentSessionID) {
      return false;
    }
    if (normalizedBoulderSessionIDs.includes(normalizeSessionId(parentSessionID))) {
      return true;
    }
    currentSessionID = parentSessionID;
  }
  return false;
}

