var TASK_SECTION_HEADER_PATTERN = /^##\s*1\.\s*TASK\s*$/i;
var TODO_TASK_LINE_PATTERN = /^(?:[-*]\s*\[\s*\]\s*)?(\d+)\.\s+(.+)$/;
