function createPreemptiveCompactionHook(ctx, pluginConfig, modelCacheState) {
  const compactionInProgress = new Set;
  const compactedSessions = new Set;
  const lastCompactionTime = new Map;
  const tokenCache = new Map;
  const postCompactionMonitor = createPostCompactionDegradationMonitor({
    client: ctx.client,
    directory: ctx.directory,
    pluginConfig,
    tokenCache,
    compactionInProgress
  });
  const toolExecuteAfter = async (input, _output) => {
    await runPreemptiveCompactionIfNeeded({
      ctx,
      pluginConfig,
      modelCacheState,
      sessionID: input.sessionID,
      tokenCache,
      compactionInProgress,
      compactedSessions,
      lastCompactionTime
    });
  };
  const eventHandler = async ({ event }) => {
    const props = event.properties;
    if (event.type === "session.deleted") {
      const sessionID = resolveSessionEventID(props);
      if (sessionID) {
        compactionInProgress.delete(sessionID);
        compactedSessions.delete(sessionID);
        lastCompactionTime.delete(sessionID);
        tokenCache.delete(sessionID);
        postCompactionMonitor.clear(sessionID);
      }
      return;
    }
    if (event.type === "session.compacted") {
      const sessionID = resolveSessionEventID(props);
      if (sessionID) {
        postCompactionMonitor.onSessionCompacted(sessionID);
      }
      return;
    }
    if (event.type === "message.updated") {
      const info = props?.info;
      const sessionID = resolveMessageEventSessionID(props);
      const finish = info?.finish;
      if (!info || info.role !== "assistant" || !finish || !sessionID)
        return;
      if (isCompactionAgent(info.agent))
        return;
      if (info.providerID && info.tokens) {
        tokenCache.set(sessionID, {
          providerID: info.providerID,
          modelID: info.modelID ?? "",
          tokens: info.tokens
        });
      }
      compactedSessions.delete(sessionID);
      await postCompactionMonitor.onAssistantMessageUpdated({
        sessionID,
        id: info.id,
        parts: info.parts
      });
    }
  };
  return {
    "tool.execute.after": toolExecuteAfter,
    event: eventHandler
  };
}
