var MISSING_SERVER_URL_ERROR = "Project Brain is enabled, but project_brain.server_url is missing. Configure project_brain.server_url before using Project Brain tools.";
var defaultProjectBrainToolDeps = {
  createProjectBrainClient,
  formatDocument,
  formatReflectionResult,
  formatSearchResult,
  formatStatus
};
function createScope(ctx, args) {
  return {
    team_id: args.team_id,
    project_id: args.project_id,
    workspace_path: ctx.directory
  };
}
function createClient(pluginConfig, deps) {
  const projectBrainConfig = pluginConfig.project_brain;
  if (!projectBrainConfig)
    return MISSING_SERVER_URL_ERROR;
  const serverUrl = projectBrainConfig.server_url?.trim();
  if (!serverUrl)
    return MISSING_SERVER_URL_ERROR;
  return deps.createProjectBrainClient({
    baseUrl: serverUrl,
    tokenEnv: projectBrainConfig.token_env,
    requestTimeoutMs: projectBrainConfig.request_timeout_ms,
    maxResults: projectBrainConfig.max_results
  });
}
async function executeProjectBrainTool(pluginConfig, deps, operationName, metadata, operation) {
  const startedAt = Date.now();
  const baseLogFields = {
    operation: operationName,
    ...metadata
  };
  log("Project Brain tool start", baseLogFields);
  try {
    const client = createClient(pluginConfig, deps);
    if (typeof client === "string") {
      log("Project Brain tool failure", {
        ...baseLogFields,
        duration_ms: Date.now() - startedAt,
        status: "error",
        status_text: "missing_server_url"
      });
      return client;
    }
    const result = await operation(client);
    log("Project Brain tool success", {
      ...baseLogFields,
      duration_ms: Date.now() - startedAt,
      status: "ok"
    });
    return result;
  } catch (error) {
    log("Project Brain tool failure", {
      ...baseLogFields,
      duration_ms: Date.now() - startedAt,
      status: "error",
      status_text: "failed"
    });
    return `Project Brain tool error: ${error instanceof Error ? error.message : String(error)}`;
  }
}
function createProjectBrainTools(pluginConfig, ctx, deps = {}) {
  const resolvedDeps = {
    ...defaultProjectBrainToolDeps,
    ...deps
  };
  const project_brain_search = tool({
    description: "Search Project Brain context for an explicit team_id and project_id.",
    args: {
      team_id: tool.schema.string().describe("Project Brain team ID. Required and explicit."),
      project_id: tool.schema.string().describe("Project Brain project ID. Required and explicit."),
      query: tool.schema.string().describe("Search query for Project Brain context."),
      max_results: tool.schema.number().int().min(1).max(100).optional().describe("Optional maximum number of context items to return.")
    },
    execute: async (args) => executeProjectBrainTool(pluginConfig, resolvedDeps, "search", {
      team_id: args.team_id,
      project_id: args.project_id,
      max_results: args.max_results ?? pluginConfig.project_brain?.max_results,
      query_length: args.query.length
    }, async (client) => resolvedDeps.formatSearchResult(await client.search({
      scope: createScope(ctx, args),
      query: args.query,
      max_results: args.max_results
    })))
  });
  const project_brain_open = tool({
    description: "Open a Project Brain source document for an explicit team_id and project_id.",
    args: {
      team_id: tool.schema.string().describe("Project Brain team ID. Required and explicit."),
      project_id: tool.schema.string().describe("Project Brain project ID. Required and explicit."),
      source_id: tool.schema.string().describe("Project Brain source ID to open.")
    },
    execute: async (args) => executeProjectBrainTool(pluginConfig, resolvedDeps, "open", {
      team_id: args.team_id,
      project_id: args.project_id,
      source_id_length: args.source_id.length
    }, async (client) => resolvedDeps.formatDocument(await client.open({
      scope: createScope(ctx, args),
      source_id: args.source_id
    })))
  });
  const project_brain_reflect = tool({
    description: "Propose a Project Brain reflection for review. This records a proposal only; it does not publish rules or policies.",
    args: {
      team_id: tool.schema.string().describe("Project Brain team ID. Required and explicit."),
      project_id: tool.schema.string().describe("Project Brain project ID. Required and explicit."),
      subject: tool.schema.string().describe("Reflection subject."),
      observation: tool.schema.string().describe("Observed fact or pattern."),
      evidence: tool.schema.array(tool.schema.string()).describe("Evidence strings supporting the observation."),
      proposal: tool.schema.string().describe("Proposed reflection content for review."),
      source_session_id: tool.schema.string().optional().describe("Optional source session ID for traceability.")
    },
    execute: async (args) => executeProjectBrainTool(pluginConfig, resolvedDeps, "reflection proposal", {
      team_id: args.team_id,
      project_id: args.project_id,
      evidence_count: args.evidence.length,
      proposal_length: args.proposal.length,
      has_source_session_id: args.source_session_id !== undefined
    }, async (client) => resolvedDeps.formatReflectionResult(await client.proposeReflection({
      scope: createScope(ctx, args),
      subject: args.subject,
      observation: args.observation,
      evidence: args.evidence,
      proposal: args.proposal,
      source_session_id: args.source_session_id
    })))
  });
  const project_brain_status = tool({
    description: "Check Project Brain status for an explicit team_id and project_id.",
    args: {
      team_id: tool.schema.string().describe("Project Brain team ID. Required and explicit."),
      project_id: tool.schema.string().describe("Project Brain project ID. Required and explicit.")
    },
    execute: async (args) => executeProjectBrainTool(pluginConfig, resolvedDeps, "status", {
      team_id: args.team_id,
      project_id: args.project_id
    }, async (client) => resolvedDeps.formatStatus(await client.status({
      scope: createScope(ctx, args)
    })))
  });
  return {
    project_brain_search,
    project_brain_open,
    project_brain_reflect,
    project_brain_status
  };
}
