// src/features/context-injector/collector.ts
var PRIORITY_ORDER = {
  critical: 0,
  high: 1,
  normal: 2,
  low: 3
};
var CONTEXT_SEPARATOR = `

---

`;
var registrationCounter = 0;

class ContextCollector {
  sessions = new Map;
  register(sessionID, options) {
    if (!this.sessions.has(sessionID)) {
      this.sessions.set(sessionID, new Map);
    }
    const sessionMap = this.sessions.get(sessionID);
    const key = `${options.source}:${options.id}`;
    const entry = {
      id: options.id,
      source: options.source,
      content: options.content,
      priority: options.priority ?? "normal",
      registrationOrder: ++registrationCounter,
      metadata: options.metadata
    };
    sessionMap.set(key, entry);
  }
  getPending(sessionID) {
    const sessionMap = this.sessions.get(sessionID);
    if (!sessionMap || sessionMap.size === 0) {
      return {
        merged: "",
        entries: [],
        hasContent: false
      };
    }
    const entries = this.sortEntries([...sessionMap.values()]);
    const merged = entries.map((e) => e.content).join(CONTEXT_SEPARATOR);
    return {
      merged,
      entries,
      hasContent: entries.length > 0
    };
  }
  consume(sessionID) {
    const pending = this.getPending(sessionID);
    this.clear(sessionID);
    return pending;
  }
  clear(sessionID) {
    this.sessions.delete(sessionID);
  }
  clearAll() {
    this.sessions.clear();
  }
  hasPending(sessionID) {
    const sessionMap = this.sessions.get(sessionID);
    return sessionMap !== undefined && sessionMap.size > 0;
  }
  sortEntries(entries) {
    return entries.sort((a, b) => {
      const priorityDiff = PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority];
      if (priorityDiff !== 0)
        return priorityDiff;
      return a.registrationOrder - b.registrationOrder;
    });
  }
}
var contextCollector = new ContextCollector;
// src/features/context-injector/injector.ts
init_shared();
function getSessionIDFromMessageInfo(info) {
  return "sessionID" in info && typeof info.sessionID === "string" ? info.sessionID : undefined;
}
function hasText(part) {
  return "text" in part && typeof part.text === "string" && part.text.length > 0;
}
function createContextInjectorMessagesTransformHook(collector) {
  return {
    "experimental.chat.messages.transform": async (_input, output) => {
      const { messages } = output;
      if (messages.length === 0) {
        return;
      }
      let lastUserMessageIndex = -1;
      for (let i = messages.length - 1;i >= 0; i--) {
        const message = messages[i];
        if (message?.info.role === "user") {
          lastUserMessageIndex = i;
          break;
        }
      }
      if (lastUserMessageIndex === -1) {
        return;
      }
      const lastUserMessage = messages[lastUserMessageIndex];
      if (lastUserMessage === undefined) {
        return;
      }
      if (!isRealUserMessage(lastUserMessage)) {
        log("[context-injector] Latest user message is synthetic/internal, skipping injection", {
          sessionID: getSessionIDFromMessageInfo(lastUserMessage.info) ?? getMainSessionID()
        });
        return;
      }
      const messageSessionID = getSessionIDFromMessageInfo(lastUserMessage.info);
      const sessionID = messageSessionID ?? getMainSessionID();
      if (!sessionID) {
        return;
      }
      const hasPending = collector.hasPending(sessionID);
      if (!hasPending) {
        return;
      }
      const textPartIndex = lastUserMessage.parts.findIndex((p) => isRealUserTextPart(p) && hasText(p));
      if (textPartIndex === -1) {
        log("[context-injector] No text part found in last user message, skipping injection", {
          sessionID,
          partsCount: lastUserMessage.parts.length
        });
        return;
      }
      const pending = collector.consume(sessionID);
      if (!pending.hasContent) {
        return;
      }
      const syntheticPart = {
        id: `prt_synthetic_hook_${sessionID}`,
        messageID: lastUserMessage.info.id,
        sessionID: messageSessionID ?? "",
        type: "text",
        text: pending.merged,
        synthetic: true
      };
      lastUserMessage.parts.splice(textPartIndex, 0, syntheticPart);
      log("[context-injector] Inserted synthetic part with hook content", {
        sessionID,
        contentLength: pending.merged.length
      });
    }
  };
}
