  const parts = [];
  if (searchTools.length > 0) {
    parts.push(...searchTools.map((tool3) => `\`${tool3.name}\``));
  }
  if (lspTools.length > 0) {
    parts.push("`lsp_*`");
  }
  if (astTools.length > 0) {
    parts.push("`ast_grep`");
  }
