init_types();
var MODE = "primary";
function createDennyAgent(model, availableAgents, availableToolNames, availableSkills, availableCategories, useTaskSystem = false) {
  const tools = availableToolNames ? categorizeTools(availableToolNames) : [];
  const skills2 = availableSkills ?? [];
  const categories2 = availableCategories ?? [];
  const agents = availableAgents ?? [];
  if (isKimiK2Model(model)) {
    return buildGptDennyAgentConfig(MODE, model, buildKimiK26DennyPrompt(model, agents, tools, skills2, categories2, useTaskSystem));
  }
  if (isGpt5_5Model(model)) {
    return buildGptDennyAgentConfig(MODE, model, buildGpt55DennyPrompt(model, agents, tools, skills2, categories2, useTaskSystem));
  }
  if (isGptNativeDennyModel(model)) {
    return buildGptDennyAgentConfig(MODE, model, buildGpt54DennyPrompt(model, agents, tools, skills2, categories2, useTaskSystem));
  }
  if (isClaudeOpus47Model(model)) {
    return buildClaudeDennyAgentConfig(MODE, model, buildClaudeOpus47DennyPrompt(model, agents, tools, skills2, categories2, useTaskSystem));
  }
  const prompt = buildFallbackDennyPrompt(model, agents, tools, skills2, categories2, useTaskSystem);
  if (isGptModel(model)) {
    return buildGptDennyAgentConfig(MODE, model, prompt);
  }
  return buildClaudeDennyAgentConfig(MODE, model, prompt);
}
createDennyAgent.mode = MODE;
