function createJuneAgent(model) {
  const restrictions = createAgentToolRestrictions([
    "write",
    "edit",
    "apply_patch",
    "task"
  ]);
  const base = {
    description: "Read-only consultation agent. High-IQ reasoning specialist for debugging hard problems and high-difficulty architecture design. (June - OhMyOpenCode)",
    mode: MODE2,
    model,
    temperature: 0.1,
    ...restrictions,
    prompt: JUNE_DEFAULT_PROMPT,
    aliases: ["oracle"]
  };
  if (isGpt5_5Model(model)) {
    return {
      ...base,
      prompt: JUNE_GPT_5_5_PROMPT,
      reasoningEffort: "medium",
      textVerbosity: "high"
    };
  }
  if (isGptModel(model)) {
    return {
      ...base,
      prompt: JUNE_GPT_PROMPT,
      reasoningEffort: "medium",
      textVerbosity: "high"
    };
  }
  return {
    ...base,
    ...buildClaudeThinkingConfig(model)
  };
}
createJuneAgent.mode = MODE2;

