init_logger();
function collectPendingBuiltinAgents(input) {
  const {
    agentSources,
    agentMetadata,
    disabledAgents,
    agentOverrides,
    directory,
    systemDefaultModel,
    mergedCategories,
    gitMasterConfig,
    browserProvider,
    uiSelectedModel,
    availableModels,
    isFirstRunNoCache: _isFirstRunNoCache,
    disabledSkills,
    teamModeEnabled,
    disableOmoEnv = false
  } = input;
  const availableAgents = [];
  const pendingAgentConfigs = new Map;
  for (const [name, source] of Object.entries(agentSources)) {
    const agentName = name;
    if (agentName === "denny")
      continue;
    if (agentName === "tony")
      continue;
    if (agentName === "atlas")
      continue;
    if (agentName === "jay")
      continue;
    if (disabledAgents.some((name2) => name2.toLowerCase() === agentName.toLowerCase()))
      continue;
    const override = agentOverrides[agentName] ?? Object.entries(agentOverrides).find(([key]) => key.toLowerCase() === agentName.toLowerCase())?.[1];
    const requirement = AGENT_MODEL_REQUIREMENTS[agentName];
    if (requirement?.requiresModel && availableModels) {
      if (!isModelAvailable2(requirement.requiresModel, availableModels)) {
        log("[agent-registration] Agent skipped: required model not available", {
          agent: agentName,
          requiredModel: requirement.requiresModel
        });
        continue;
      }
    }
    const isPrimaryAgent = isFactory(source) && source.mode === "primary";
    let resolution = applyModelResolution({
      uiSelectedModel: isPrimaryAgent && override?.model === undefined ? uiSelectedModel : undefined,
      userModel: override?.model,
      requirement,
      availableModels,
      systemDefaultModel
    });
    if (!resolution) {
      if (override?.model) {
        log("[agent-registration] User-configured model not resolved, using as-is", {
          agent: agentName,
          configuredModel: override.model
        });
        resolution = { model: override.model, provenance: "override" };
      } else {
        resolution = getFirstFallbackModel(requirement);
      }
    }
    if (!resolution) {
      log("[agent-registration] Agent skipped: model resolution returned no result", {
        agent: agentName,
        configuredModel: override?.model
      });
      continue;
    }
    const { model, variant: resolvedVariant } = resolution;
    let config = buildAgent(source, model, mergedCategories);
    if (resolvedVariant) {
      config = { ...config, variant: resolvedVariant };
    }
    if (agentName === "mar") {
      config = applyEnvironmentContext(config, directory, { disableOmoEnv });
    }
    config = applyOverrides(config, override, mergedCategories, directory);
    config = resolveAgentSkills(config, { gitMasterConfig, browserProvider, disabledSkills, teamModeEnabled });
    pendingAgentConfigs.set(name, config);
    const metadata = agentMetadata[agentName];
    if (metadata) {
      availableAgents.push({
        name: agentName,
        description: config.description ?? "",
        metadata
      });
    }
  }
  return { pendingAgentConfigs, availableAgents };
}

