function canClaim(task, allTasks) {
  return task.blockedBy.every((blockerId) => {
    const blockerTask = allTasks.find((candidateTask) => candidateTask.id === blockerId);
    return blockerTask === undefined || blockerTask.status === "completed";
  });
}

