// src/plugin/tool-registry-trimming.ts
init_shared();
var LOW_PRIORITY_TOOL_ORDER = [
  "session_list",
  "session_read",
  "session_search",
  "session_info",
  "interactive_bash",
  "look_at",
  "call_omo_agent",
  "task_create",
  "task_get",
  "task_list",
  "task_update",
  "background_output",
  "background_cancel",
  "edit",
  "ast_grep_replace",
  "ast_grep_search",
  "glob",
  "grep",
  "skill_mcp",
  "skill",
  "task",
  "lsp_rename",
  "lsp_prepare_rename",
  "lsp_find_references",
  "lsp_goto_definition",
  "lsp_symbols",
  "lsp_diagnostics"
];
function trimToolsToCap(filteredTools, maxTools) {
  const toolNames = Object.keys(filteredTools);
  if (toolNames.length <= maxTools)
    return;
  const removableToolNames = [
    ...LOW_PRIORITY_TOOL_ORDER.filter((toolName) => toolNames.includes(toolName)),
    ...toolNames.filter((toolName) => !LOW_PRIORITY_TOOL_ORDER.includes(toolName)).sort()
  ];
  let currentCount = toolNames.length;
  let removed = 0;
  for (const toolName of removableToolNames) {
    if (currentCount <= maxTools)
      break;
    if (!filteredTools[toolName])
      continue;
    delete filteredTools[toolName];
    currentCount -= 1;
    removed += 1;
  }
  log(`[tool-registry] Trimmed ${removed} tools to satisfy max_tools=${maxTools}. Final plugin tool count=${currentCount}.`);
}
// src/plugin/tool-registry.ts
function createToolRegistry(args) {
  const {
    ctx,
    pluginConfig,
    managers,
    skillContext,
    availableCategories,
    interactiveBashEnabled = isInteractiveBashEnabled(),
    toolFactories
  } = args;
  const factories = {
    ...defaultToolRegistryFactories,
    ...toolFactories
  };
  const taskSystemEnabled = getTaskSystemEnabled(pluginConfig);
  const allTools = {
    ...createCoreTools({
      ctx,
      pluginConfig,
      managers,
      skillContext,
      availableCategories,
      factories
    }),
    ...interactiveBashEnabled ? { interactive_bash: factories.interactive_bash } : {},
    ...createTeamModeToolsRecord({ pluginConfig, ctx, managers, factories }),
    ...createTaskToolsRecord({ taskSystemEnabled, pluginConfig, ctx, factories }),
    ...createHashlineToolsRecord({ pluginConfig, ctx, factories }),
    ...createConsensusToolsRecord({ pluginConfig, ctx, factories }),
    ...createProjectBrainToolsRecord({ pluginConfig, ctx, factories })
  };
  const allToolNames = Object.keys(allTools);
  const teamToolCount = allToolNames.filter((toolName) => toolName.startsWith("team_")).length;
  log("[tool-registry] Built tool registry", {
    totalTools: allToolNames.length,
    teamModeEnabled: pluginConfig.team_mode?.enabled ?? false,
    teamToolCount
  });
  for (const toolDefinition of Object.values(allTools)) {
    normalizeToolArgSchemas(toolDefinition);
  }
  const filteredTools = filterDisabledTools(allTools, pluginConfig.disabled_tools);
  const maxTools = pluginConfig.experimental?.max_tools;
  if (maxTools) {
    trimToolsToCap(filteredTools, maxTools);
  }
  return {
    filteredTools,
    taskSystemEnabled
  };
}

// src/create-tools.ts
async function createTools(args) {
  const { ctx, pluginConfig, managers } = args;
  const skillContext = await createSkillContext({
    directory: ctx.directory,
    pluginConfig
  });
  const availableCategories = createAvailableCategories(pluginConfig);
  const { filteredTools, taskSystemEnabled } = createToolRegistry({
    ctx,
    pluginConfig,
    managers,
    skillContext,
    availableCategories
  });
  return {
    filteredTools,
    mergedSkills: skillContext.mergedSkills,
    availableSkills: skillContext.availableSkills,
    availableCategories,
    browserProvider: skillContext.browserProvider,
    disabledSkills: skillContext.disabledSkills,
    taskSystemEnabled
  };
}

// src/plugin-dispose.ts
init_shared();
function createPluginDispose(args) {
  const { backgroundManager, skillMcpManager, disposeHooks } = args;
  let disposePromise = null;
  return async () => {
    if (disposePromise) {
      await disposePromise;
      return;
    }
    disposePromise = (async () => {
      try {
        await backgroundManager.shutdown();
      } catch (error) {
        log("[plugin-dispose] backgroundManager.shutdown() error:", error);
      }
      try {
        await skillMcpManager.disconnectAll();
      } catch (error) {
        log("[plugin-dispose] skillMcpManager.disconnectAll() error:", error);
      }
      try {
        disposeHooks();
      } catch (error) {
        log("[plugin-dispose] disposeHooks() error:", error);
      }
    })();
    await disposePromise;
  };
}

